rawInput.command:
$root = "C:\Users\magicvr\AppData\Local\Temp\gg-goal018-s3-b4812a31\docs"
Write-Output "=== canonical workspaces ==="
Get-ChildItem -LiteralPath (Join-Path $root "workspaces") -Force -ErrorAction SilentlyContinue | ForEach-Object { $_.Name + " | " + $_.Attributes + " | link=" + $_.LinkType }
Write-Output "=== legacy direct workspace-* ==="
Get-ChildItem -LiteralPath $root -Force -Directory | Where-Object { $_.Name -like "workspace-*" } | ForEach-Object { $_.FullName }
Write-Output "=== legacy goals ==="
$goals = Join-Path $root "goals"
Write-Output ("goals_exists=" + (Test-Path -LiteralPath $goals))
Write-Output "=== workspace-002 dirs ==="
Get-ChildItem -LiteralPath (Join-Path $root "workspaces") -Force -Directory | Where-Object { $_.Name -match '^workspace-002(-|$)' } | ForEach-Object {
  $ws = $_
  Write-Output ("DIR=" + $ws.FullName + " link=" + $ws.LinkType + " attrs=" + $ws.Attributes)
  Get-ChildItem -LiteralPath $ws.FullName -Force | ForEach-Object { "  " + $_.Name + " | " + $_.Attributes + " | " + $_.LinkType }
}

